function toolMeta(id){for(const group of toolGroups){const tool=group.tools.find(item=>item.id===id);if(tool)return {...tool,group};}return null;}
function closeToolFlyouts(except=null){document.querySelectorAll('.ps-tool-group.open').forEach(group=>{if(group!==except)group.classList.remove('open');});}
function buildTools(){const panel=document.getElementById('toolsPanel');toolGroups.forEach(group=>{group.activeId=group.tools[0].id;const wrapper=document.createElement('div');wrapper.className=`ps-tool-group${group.id==='move'?' active':''}`;wrapper.dataset.toolGroup=group.id;const main=document.createElement('button');main.type='button';main.className='ps-tool';main.dataset.tool=group.activeId;main.title=group.tools[0].name;main.innerHTML=`${iconMarkup(group.tools[0].icon,'ps-tool-icon')}<kbd>${group.key}</kbd>`;wrapper.append(main);if(group.tools.length>1){const toggle=document.createElement('button');toggle.type='button';toggle.className='ps-tool-flyout-toggle';toggle.innerHTML=iconMarkup('lrs-arrow_right','ps-tool-flyout-arrow');const flyout=document.createElement('div');flyout.className='ps-tool-flyout';group.tools.forEach(tool=>{const item=document.createElement('button');item.type='button';item.className='ps-tool-flyout-item';item.dataset.tool=tool.id;item.innerHTML=`${iconMarkup(tool.icon,'ps-tool-icon')}<span>${escapeHtml(tool.name)}</span><kbd>${group.key}</kbd>`;flyout.append(item);});toggle.addEventListener('click',event=>{event.stopPropagation();const opening=!wrapper.classList.contains('open');closeToolFlyouts();wrapper.classList.toggle('open',opening);});wrapper.addEventListener('contextmenu',event=>{event.preventDefault();closeToolFlyouts();wrapper.classList.add('open');});wrapper.append(toggle,flyout);}panel.append(wrapper);});}
function selectTool(tool){const meta=toolMeta(tool);if(!meta)return;meta.group.activeId=tool;state.tool=tool;document.querySelectorAll('.ps-tool-group').forEach(wrapper=>wrapper.classList.toggle('active',wrapper.dataset.toolGroup===meta.group.id));const groupButton=document.querySelector(`[data-tool-group="${meta.group.id}"] > .ps-tool`);if(groupButton){groupButton.dataset.tool=tool;groupButton.title=meta.name;groupButton.innerHTML=`${iconMarkup(meta.icon,'ps-tool-icon')}<kbd>${meta.group.key}</kbd>`;}document.getElementById('activeToolIcon').innerHTML=iconMarkup(meta.icon);document.getElementById('activeToolName').textContent=meta.name;closeToolFlyouts();const stage=document.getElementById('stageViewport');stage.classList.toggle('zoom-tool',tool==='zoom');stage.classList.toggle('selection-tool',tool==='marquee'||tool==='lasso');if(!['move','marquee','lasso','zoom','horizontal-type'].includes(tool))toast(`${meta.name} will be added in a later version.`);updateMoveable();}

function selectClipboardDocument(selected){state.newDocumentUsesClipboard=Boolean(selected&&state.newDocumentClipboard);document.getElementById('clipboardDocumentCard').classList.toggle('selected',state.newDocumentUsesClipboard);}
function applyClipboardDocumentDimensions(){const clipboard=state.newDocumentClipboard;if(!clipboard)return;document.getElementById('projectWidth').value=clipboard.width;document.getElementById('projectHeight').value=clipboard.height;document.getElementById('documentUnit').value='px';selectedDocumentTemplateId=null;selectClipboardDocument(true);renderTemplateGrid();}
async function showClipboardDocumentCard(token){const card=document.getElementById('clipboardDocumentCard');try{const items=await navigator.clipboard?.read?.();if(!items||token!==state.clipboardReadToken)return;const item=items.find(entry=>entry.types.some(type=>type.startsWith('image/'))),type=item?.types.find(candidate=>candidate==='image/png')||item?.types.find(candidate=>candidate.startsWith('image/'));if(!item||!type)return;const png=await imageFileToPng(await item.getType(type)),dialog=document.getElementById('newProjectDialog');if(token!==state.clipboardReadToken||!dialog.open)return;state.newDocumentClipboard=png;document.getElementById('clipboardDocumentDimensions').textContent=`${png.width} × ${png.height} px`;const preview=document.getElementById('clipboardDocumentPreview'),image=await loadImage(png.dataUrl),scale=Math.min(1,88/png.width,88/png.height);preview.width=Math.max(1,Math.round(png.width*scale));preview.height=Math.max(1,Math.round(png.height*scale));preview.getContext('2d').drawImage(image,0,0,preview.width,preview.height);card.hidden=false;applyClipboardDocumentDimensions();}catch{card.hidden=true;}}
function openNewProjectDialog(){const dialog=document.getElementById('newProjectDialog'),card=document.getElementById('clipboardDocumentCard'),token=++state.clipboardReadToken;state.newDocumentClipboard=null;selectClipboardDocument(false);card.hidden=true;dialog.showModal();showClipboardDocumentCard(token);}
function renderTemplateCategories(){const nav=document.getElementById('templateCategories');nav.replaceChildren(...documentTemplateCategories.map(category=>{const button=document.createElement('button');button.type='button';button.textContent=category.label;button.classList.toggle('active',category.id===activeTemplateCategory);button.addEventListener('click',()=>{activeTemplateCategory=category.id;selectedDocumentTemplateId=null;renderTemplateCategories();renderTemplateGrid();});return button;}));}
function renderTemplateGrid(){const grid=document.getElementById('templateGrid'),category=documentTemplateCategories.find(item=>item.id===activeTemplateCategory);grid.replaceChildren(...(category?.templates||[]).map(template=>{const card=document.createElement('button');card.type='button';card.className='ps-template-card';card.classList.toggle('selected',template.id===selectedDocumentTemplateId);const scale=Math.min(166/Number(template.width),106/Number(template.height)),preview=document.createElement('span');preview.className='ps-template-preview';preview.style.width=`${Math.max(2,Number(template.width)*scale)}px`;preview.style.height=`${Math.max(2,Number(template.height)*scale)}px`;const title=document.createElement('strong');title.textContent=template.title||'';title.hidden=!template.title;const dimensions=document.createElement('span');dimensions.className='ps-template-dimensions';dimensions.textContent=template.display;card.append(preview,title,dimensions);card.addEventListener('click',()=>selectDocumentTemplate(template));return card;}));}
function selectDocumentTemplate(template){selectedDocumentTemplateId=template.id;selectClipboardDocument(false);document.getElementById('projectWidth').value=template.width;document.getElementById('projectHeight').value=template.height;document.getElementById('documentUnit').value=template.unit;document.getElementById('documentDpi').value=template.dpi;renderTemplateGrid();}
function documentPixelDimensions(){const width=Number(document.getElementById('projectWidth').value),height=Number(document.getElementById('projectHeight').value),dpi=Number(document.getElementById('documentDpi').value),unit=document.getElementById('documentUnit').value,multiplier=unit==='in'?dpi:unit==='mm'?dpi/25.4:1;return {width:Math.round(width*multiplier),height:Math.round(height*multiplier)};}
async function loadDocumentTemplates(){const response=await fetch('/photoshop-templates.json');if(!response.ok)throw new Error('Could not load document templates.');documentTemplateCategories=(await response.json()).categories||[];activeTemplateCategory=documentTemplateCategories[0]?.id||'social';renderTemplateCategories();renderTemplateGrid();}

document.addEventListener('click',event=>{if(!event.target.closest('.ps-menu'))closeMenus();if(!event.target.closest('.ps-tool-group'))closeToolFlyouts();if(!event.target.closest('#opacityControl'))document.getElementById('opacityPopover').hidden=true;const action=event.target.closest('[data-action]')?.dataset.action;if(action)actions[action]?.();const tool=event.target.closest('[data-tool]')?.dataset.tool;if(tool)selectTool(tool);const panel=event.target.closest('[data-inspector-panel]')?.dataset.inspectorPanel;if(panel)toggleInspectorPanel(panel);const align=event.target.closest('[data-align-layer]')?.dataset.alignLayer;if(align)alignActiveLayers(align);});
document.addEventListener('keydown',event=>{const mod=event.ctrlKey||event.metaKey,key=event.key.toLowerCase();if(mod&&key==='z'){event.preventDefault();event.shiftKey?actions.redo():actions.undo();return;}if(mod&&key==='y'){event.preventDefault();actions.redo();return;}if(mod&&key==='s'){event.preventDefault();exportActiveProjectAsPsd();return;}if(mod&&(key==='+'||key==='=')){event.preventDefault();actions.zoomIn();return;}if(mod&&key==='-'){event.preventDefault();actions.zoomOut();return;}if(['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;let action=null;if(mod&&key==='n')action='newProject';if(mod&&key==='o')action='openLocal';if(mod&&key==='a')action='selectAll';if(mod&&key==='c')action='copy';if(mod&&key==='v')action='paste';if(mod&&key==='d')action='deselect';if(mod&&event.key==='0')action='fitScreen';if(mod&&event.key==='1')action='actualPixels';if(action){event.preventDefault();actions[action]?.();}if(!mod&&['v','m','l','t','z'].includes(key))selectTool(key==='m'?'marquee':key==='l'?'lasso':key==='v'?'move':key==='t'?'horizontal-type':'zoom');if(!mod&&event.key==='Delete'){event.preventDefault();actions.deleteLayers();}});
document.getElementById('newProjectForm').addEventListener('submit',event=>{event.preventDefault();if(event.submitter?.value==='cancel'){document.getElementById('newProjectDialog').close();return;}const dimensions=documentPixelDimensions();if(dimensions.width<1||dimensions.height<1||dimensions.width>8192||dimensions.height>8192){toast('Document dimensions must resolve to between 1 and 8,192 pixels.');return;}const clipboard=state.newDocumentUsesClipboard?state.newDocumentClipboard:null,project={id:nextProjectId(),name:document.getElementById('newProjectName').value,width:dimensions.width,height:dimensions.height,layers:[]},canvas=transparentCanvas(dimensions.width,dimensions.height);project.layers.push(newLayer(project,{name:clipboard?'Clipboard':'Layer 1',dataUrl:clipboard?.dataUrl||canvasToDataUrl(canvas),width:dimensions.width,height:dimensions.height,z_index:0}));createLocalProject({...project,historyLabel:clipboard?'Create from Clipboard':'New',clean:false});state.newDocumentClipboard=null;state.newDocumentUsesClipboard=false;document.getElementById('newProjectDialog').close();});
document.getElementById('clipboardDocumentCard').addEventListener('click',applyClipboardDocumentDimensions);
document.getElementById('swapDimensions').addEventListener('click',()=>{const width=document.getElementById('projectWidth'),height=document.getElementById('projectHeight'),next=width.value;width.value=height.value;height.value=next;selectedDocumentTemplateId=null;selectClipboardDocument(false);renderTemplateGrid();});
for(const id of ['projectWidth','projectHeight','documentUnit','documentDpi'])document.getElementById(id).addEventListener('input',()=>{selectedDocumentTemplateId=null;selectClipboardDocument(false);renderTemplateGrid();});
