function enableDialogDrag(dialog){const handle=dialog.querySelector('.ps-draggable-dialog-handle');handle.addEventListener('pointerdown',event=>{if(event.target.closest('button'))return;event.preventDefault();const rect=dialog.getBoundingClientRect(),offsetX=event.clientX-rect.left,offsetY=event.clientY-rect.top,pointerId=event.pointerId;dialog.style.margin='0';dialog.style.left=rect.left+'px';dialog.style.top=rect.top+'px';handle.setPointerCapture(pointerId);const move=next=>{if(next.pointerId!==pointerId)return;dialog.style.left=Math.max(0,Math.min(window.innerWidth-rect.width,next.clientX-offsetX))+'px';dialog.style.top=Math.max(0,Math.min(window.innerHeight-rect.height,next.clientY-offsetY))+'px';};const finish=next=>{if(next.pointerId!==pointerId)return;if(handle.hasPointerCapture(pointerId))handle.releasePointerCapture(pointerId);handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',finish);};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',finish);});}
enableDialogDrag(document.getElementById('genAiPromptDialog'));;
document.getElementById('deleteLayersForm').addEventListener('submit',event=>{event.preventDefault();if(event.submitter?.value==='delete')deleteSelectedItems();else document.getElementById('deleteLayersDialog').close();});
const opacityInput=document.getElementById('layerOpacity'),opacitySlider=document.getElementById('layerOpacitySlider'),opacityPopover=document.getElementById('opacityPopover');
function showOpacitySlider(){if(activeLayer())opacityPopover.hidden=false;}
document.getElementById('opacityTrigger').addEventListener('click',()=>{if(activeLayer())opacityPopover.hidden=!opacityPopover.hidden;});
opacityInput.addEventListener('click',showOpacitySlider);
opacityInput.addEventListener('change',event=>{const layer=activeLayer();if(!layer)return;const value=Math.max(0,Math.min(100,Number(event.target.value)||0));event.target.value=value;opacitySlider.value=value;updateLayer(layer,{opacity:value},'Opacity Change').then(renderCanvas);});
opacitySlider.addEventListener('focus',()=>{const layer=activeLayer();if(layer)opacitySlider.dataset.start=String(layer.opacity);});
opacitySlider.addEventListener('pointerdown',()=>{const layer=activeLayer();if(layer)opacitySlider.dataset.start=String(layer.opacity);});
opacitySlider.addEventListener('input',event=>{const layer=activeLayer();if(!layer)return;layer.opacity=Number(event.target.value);opacityInput.value=event.target.value;refreshDirty(activeProject());renderCanvas();renderProperties();});
opacitySlider.addEventListener('change',()=>{const layer=activeLayer();if(layer&&Number(opacitySlider.dataset.start)!==layer.opacity)recordHistory('Opacity Change');});
document.getElementById('layerBlendMode').addEventListener('change',event=>{const layer=activeLayer();if(layer)updateLayer(layer,{blendMode:event.target.value},'Blending Change').then(renderCanvas);});
document.getElementById('transformControls').addEventListener('change',updateMoveable);
document.getElementById('propertiesPanel').addEventListener('change',event=>{const input=event.target.closest('[data-layer-property]'),layer=activeLayer();if(!input||!layer)return;const property=input.dataset.layerProperty,value=Number(input.value);if(Number.isFinite(value))updateLayer(layer,{[property]:value},property==='opacity'?'Opacity Change':'Transform').then(render);});
function beginZoomScrub(event){if(state.tool!=='zoom'||!activeProject()||event.button!==0)return;event.preventDefault();const viewport=event.currentTarget,pointerId=event.pointerId,startX=event.clientX,startZoom=state.zoom;let pendingZoom=startZoom,frame=0;viewport.setPointerCapture(pointerId);viewport.classList.add('zoom-scrubbing');const move=next=>{if(next.pointerId!==pointerId)return;pendingZoom=startZoom*Math.pow(2,(next.clientX-startX)/180);if(!frame)frame=requestAnimationFrame(()=>{frame=0;setZoom(pendingZoom);});};const finish=next=>{if(next.pointerId!==pointerId)return;if(frame){cancelAnimationFrame(frame);frame=0;setZoom(pendingZoom);}viewport.classList.remove('zoom-scrubbing');if(viewport.hasPointerCapture(pointerId))viewport.releasePointerCapture(pointerId);viewport.removeEventListener('pointermove',move);viewport.removeEventListener('pointerup',finish);viewport.removeEventListener('pointercancel',finish);};viewport.addEventListener('pointermove',move);viewport.addEventListener('pointerup',finish);viewport.addEventListener('pointercancel',finish);}
const zoomStatusInput=document.getElementById('zoomStatusInput');
function commitZoomStatus(){const percent=Number.parseFloat(zoomStatusInput.value.replace('%',''));if(activeProject()&&Number.isFinite(percent)&&percent>0)setZoom(percent/100);else updateDocumentStatus();}
zoomStatusInput.addEventListener('focus',()=>zoomStatusInput.select());
zoomStatusInput.addEventListener('change',commitZoomStatus);
zoomStatusInput.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();commitZoomStatus();zoomStatusInput.blur();}if(event.key==='Escape'){event.preventDefault();updateDocumentStatus();zoomStatusInput.blur();}});
document.getElementById('stageViewport').addEventListener('pointerdown',beginZoomScrub);
document.getElementById('stageViewport').addEventListener('pointermove',event=>{const project=activeProject(),canvas=document.getElementById('canvas');if(!project||!canvas)return;const rect=canvas.getBoundingClientRect();state.infoPointer={x:(event.clientX-rect.left)/state.zoom,y:(event.clientY-rect.top)/state.zoom};if(state.inspectorPanel==='info')sampleInfoAt(state.infoPointer);});
document.getElementById('stageViewport').addEventListener('pointerleave',()=>{state.infoPointer=null;if(state.inspectorPanel==='info')updateInfoReadout(null);});
document.getElementById('galleryKeywords').addEventListener('input',renderGalleryPanel);
function updateSelectionDimensionsTooltip(event,selection){
    const tooltip=document.getElementById('selectionDimensionsTooltip');if(!selection){tooltip.hidden=true;return;}
    tooltip.querySelector('[data-selection-width]').textContent=Math.round(Math.abs(selection.width||0))+' px';tooltip.querySelector('[data-selection-height]').textContent=Math.round(Math.abs(selection.height||0))+' px';tooltip.hidden=false;
    const gap=14,left=Math.min(event.clientX+gap,window.innerWidth-tooltip.offsetWidth-8),top=Math.min(event.clientY+gap,window.innerHeight-tooltip.offsetHeight-8);tooltip.style.left=Math.max(8,left)+'px';tooltip.style.top=Math.max(8,top)+'px';
}
function hideSelectionDimensionsTooltip(){document.getElementById('selectionDimensionsTooltip').hidden=true;}
function clampedCanvasPoint(event,canvas,project){const rect=canvas.getBoundingClientRect(),x=(event.clientX-rect.left)/state.zoom,y=(event.clientY-rect.top)/state.zoom;return {x:Math.max(0,Math.min(project.width,x)),y:Math.max(0,Math.min(project.height,y))};}
function beginMarqueeSelection(event){if(state.tool!=='marquee'||!activeProject()||event.button!==0)return;event.preventDefault();const viewport=event.currentTarget,project=activeProject(),canvas=document.getElementById('canvas'),pointerId=event.pointerId,start=clampedCanvasPoint(event,canvas,project);viewport.setPointerCapture(pointerId);selectArea({x:start.x,y:start.y,width:0,height:0});updateSelectionDimensionsTooltip(event,state.selection);const move=next=>{if(next.pointerId!==pointerId)return;const current=clampedCanvasPoint(next,canvas,project);selectArea({x:Math.min(start.x,current.x),y:Math.min(start.y,current.y),width:Math.abs(current.x-start.x),height:Math.abs(current.y-start.y)});updateSelectionDimensionsTooltip(next,state.selection);};const finish=next=>{if(next.pointerId!==pointerId)return;hideSelectionDimensionsTooltip();if(viewport.hasPointerCapture(pointerId))viewport.releasePointerCapture(pointerId);viewport.removeEventListener('pointermove',move);viewport.removeEventListener('pointerup',finish);viewport.removeEventListener('pointercancel',finish);};viewport.addEventListener('pointermove',move);viewport.addEventListener('pointerup',finish);viewport.addEventListener('pointercancel',finish);}
document.getElementById('stageViewport').addEventListener('pointerdown',beginMarqueeSelection);
function beginLassoSelection(event){if(state.tool!=='lasso'||!activeProject()||event.button!==0)return;event.preventDefault();const viewport=event.currentTarget,project=activeProject(),canvas=document.getElementById('canvas'),pointerId=event.pointerId,points=[clampedCanvasPoint(event,canvas,project)],minimumDistance=1.5/state.zoom;viewport.setPointerCapture(pointerId);state.selection=lassoSelectionFromPoints(points,false);renderSelection();updateSelectionDimensionsTooltip(event,state.selection);const appendPoint=sample=>{const point=clampedCanvasPoint(sample,canvas,project),last=points.at(-1),distance=(point.x-last.x)**2+(point.y-last.y)**2;if(distance>=minimumDistance**2)points.push(point);};const move=next=>{if(next.pointerId!==pointerId)return;(next.getCoalescedEvents?.()||[next]).forEach(appendPoint);state.selection=lassoSelectionFromPoints(points,false);renderSelection();updateSelectionDimensionsTooltip(next,state.selection);};const finish=next=>{if(next.pointerId!==pointerId)return;appendPoint(next);hideSelectionDimensionsTooltip();if(viewport.hasPointerCapture(pointerId))viewport.releasePointerCapture(pointerId);viewport.removeEventListener('pointermove',move);viewport.removeEventListener('pointerup',finish);viewport.removeEventListener('pointercancel',finish);if(points.length<3)clearSelection();else{state.selection=lassoSelectionFromPoints(points,true);renderSelection();}};viewport.addEventListener('pointermove',move);viewport.addEventListener('pointerup',finish);viewport.addEventListener('pointercancel',finish);}
document.getElementById('stageViewport').addEventListener('pointerdown',beginLassoSelection);
document.getElementById('stageViewport').addEventListener('pointerdown',beginGenAiRegionSelection);
document.getElementById('canvas').addEventListener('pointerdown',event=>{if(state.tool!=='horizontal-type')return;const canvas=event.currentTarget,project=activeProject(),point=clampedCanvasPoint(event,canvas,project);addTextLayerAt(point.x,point.y);});
window.addEventListener('resize',()=>{if(activeProject())fitScreen();else updateDocumentStatus();});
window.addEventListener('beforeunload',()=>{state.binaryAssetUrls.forEach(url=>URL.revokeObjectURL(url));const previewUrl=document.getElementById('imageSizePreview')?.dataset.objectUrl;if(previewUrl)URL.revokeObjectURL(previewUrl);});

